:root {
  --bg: #2d1b4e;
  --card-bg: #3d2a6b;
  --accent: #f7c948;
  --text: #f0e6ff;
  --bar-bg: #1e1235;
  --hunger: #ff6b6b;
  --happiness: #f7c948;
  --energy: #4ecdc4;
  --focus: #ffffff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.game-board {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.6rem;
  letter-spacing: 2px;
  color: var(--accent);
}

.pet-container {
  display: flex;
  justify-content: center;
  padding: 12px 0;
}

.pet {
  width: 120px;
  height: 120px;
  background: var(--accent);
  border-radius: 16px;
  position: relative;
  image-rendering: pixelated;
  box-shadow: 0 0 0 6px var(--bar-bg);
  transition: transform 0.2s;
}

.pet:active {
  transform: scale(0.95);
}

.pixel {
  position: absolute;
  background: var(--bar-bg);
}

.eye {
  width: 16px;
  height: 16px;
  top: 32px;
  border-radius: 2px;
}

.eye.left { left: 28px; }
.eye.right { right: 28px; }

.mouth {
  width: 32px;
  height: 8px;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  border-radius: 2px;
}

.mood {
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--accent);
  min-height: 1.6em;
}

.bars {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.bar-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
  text-align: left;
}

.bar-label {
  font-size: 0.9rem;
  opacity: 0.8;
}

.bar-track {
  height: 18px;
  background: var(--bar-bg);
  border-radius: 9px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 50%;
  border-radius: 9px;
  transition: width 0.4s ease;
}

.bar-fill.hunger { background: var(--hunger); }
.bar-fill.happiness { background: var(--happiness); }
.bar-fill.energy { background: var(--energy); }

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  flex: 1 1 0;
  min-width: 100px;
  padding: 14px 12px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--bar-bg);
  background: var(--accent);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

button:hover {
  background: #ffe07a;
}

button:active {
  transform: scale(0.96);
  background: #e0b030;
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

@media (max-width: 360px) {
  .game-board {
    padding: 24px 16px;
  }
  button {
    min-width: 80px;
    padding: 12px 8px;
    font-size: 0.95rem;
  }
}

(function() {
  'use strict';

  const state = {
    hunger: 50,
    happiness: 50,
    energy: 50
  };

  const moodEl = document.getElementById('mood');
  const bars = {
    hunger: document.getElementById('hungerBar'),
    happiness: document.getElementById('happinessBar'),
    energy: document.getElementById('energyBar')
  };

  function clamp(value) {
    return Math.max(0, Math.min(100, value));
  }

  function updateMood() {
    const { hunger, happiness, energy } = state;
    let mood = 'Happy';
    if (hunger < 30) mood = 'Hungry';
    else if (energy < 30) mood = 'Tired';
    else if (happiness < 30) mood = 'Sad';
    else if (hunger > 70 && happiness > 70 && energy > 70) mood = 'Thriving';
    else if (happiness > 70) mood = 'Playful';
    moodEl.textContent = mood;
  }

  function updateBars() {
    for (const key of Object.keys(bars)) {
      const bar = bars[key];
      bar.style.width = state[key] + '%';
      bar.setAttribute('aria-valuenow', state[key]);
      bar.textContent = state[key];
    }
  }

  function updateUI() {
    updateBars();
    updateMood();
  }

  function feed() {
    state.hunger = clamp(state.hunger + 20);
    state.happiness = clamp(state.happiness + 5);
    state.energy = clamp(state.energy - 5);
    updateUI();
  }

  function play() {
    state.happiness = clamp(state.happiness + 20);
    state.energy = clamp(state.energy - 15);
    state.hunger = clamp(state.hunger - 10);
    updateUI();
  }

  function sleep() {
    state.energy = clamp(state.energy + 30);
    state.hunger = clamp(state.hunger - 5);
    state.happiness = clamp(state.happiness - 5);
    updateUI();
  }

  document.getElementById('feedBtn').addEventListener('click', feed);
  document.getElementById('playBtn').addEventListener('click', play);
  document.getElementById('sleepBtn').addEventListener('click', sleep);

  updateUI();
})();
